  return `${head('Stok','Produk jual dan perlengkapan operasional ditampilkan terpisah.',`<button class="btn" data-action="stock" ${profile.role!=='owner'?'disabled':''}>＋ Tambah / Perbarui Stok</button>`)}<div class="grid split">${categories.map(([cat,title])=>{const items=data.inventory.filter(i=>i.store_id===profile.store_id&&i.category===cat);return card(`<h2 class="section-title">${title}</h2><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Jumlah</th><th>Batas minimum</th><th>Biaya/unit</th><th>Status</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.name)}${i.is_demo?'<span class="demo-label">demo</span>':''}</td><td>${i.quantity} ${esc(i.unit)}</td><td>${i.minimum_quantity} ${esc(i.unit)}</td><td>${money(i.unit_cost)}</td><td><span class="tag ${Number(i.quantity)<=Number(i.minimum_quantity)?'bad':'good'}">${Number(i.quantity)<=Number(i.minimum_quantity)?'Perlu restok':'Cukup'}</span></td></tr>`).join('')||`<tr><td colspan="5">Belum ada barang.</td></tr>`}</tbody></table></div>`)}).join('')}</div>`;
