function expensePage(){const rows=data.expenses.filter(e=>e.store_id===profile.store_id);const sum=todayExpenses().reduce((s,e)=>s+Number(e.amount),0);return `${head('Catatan pengeluaran','Catat biaya berdasarkan kategori dan metode pembayaran.',`<button class="btn" data-action="expense">＋ Catat Pengeluaran</button>`)}${card(`<div class="stat-label">Total pengeluaran hari ini</div><div class="stat-value">${money(sum)}</div>`)}<div style="margin-top:14px">${card(`<h2 class="section-title">Riwayat pengeluaran</h2><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Catatan</th><th>Metode</th><th>Jumlah</th></tr></thead><tbody>${rows.slice(0,100).map(e=>`<tr><td>${dateLabel(e.spent_at)}</td><td>${esc(e.category)}</td><td>${esc(e.note)}</td><td>${esc(e.payment_method)}</td><td>${money(e.amount)}</td></tr>`).join('')||`<tr><td colspan="5">Belum ada catatan pengeluaran.</td></tr>`}</tbody></table></div>`)}</div>`}

function cashPage(){const balances=paymentMethods.map(m=>{const received=data.payments.filter(p=>p.store_id===profile.store_id&&p.payment_method===m).reduce((s,p)=>s+Number(p.amount),0),spent=data.expenses.filter(e=>e.store_id===profile.store_id&&e.payment_method===m).reduce((s,e)=>s+Number(e.amount),0);return [m,received,spent,received-spent]});return `${head('Kas & pembayaran','Ringkasan uang masuk dan pengeluaran berdasarkan tiga metode yang digunakan.') }<div class="grid thirds">${balances.map(([m,got,out,bal])=>card(`<div class="stat-label">${m}</div><div class="stat-value">${money(bal)}</div><div class="stat-foot">${money(got)} diterima · ${money(out)} pengeluaran</div>`)).join('')}</div><div style="margin-top:14px">${card(`<h2 class="section-title">Metode pembayaran</h2><p class="section-sub">Transaksi hanya menerima pilihan berikut:</p><div class="inline">${paymentMethods.map(m=>`<span class="tag">${m}</span>`).join('')}</div><p class="notice" style="margin-top:14px">Saldo adalah akumulasi data transaksi yang dicatat sejak sistem digunakan. Saldo tidak terhubung otomatis ke rekening atau penyedia QR.</p>`)}</div>`}

function closingPage(){const day=localDate(),closing=data.closings.find(c=>c.business_date===day),tx=currentTransactions().filter(t=>localDate(t.paid_at||t.created_at)===day&&t.status==='paid'),expenses=todayExpenses();const expected=m=>tx.filter(t=>t.payment_method===m).reduce((s,t)=>s+Number(t.total),0)-expenses.filter(e=>e.payment_method===m).reduce((s,e)=>s+Number(e.amount),0);return `${head('Tutup buku harian','Cocokkan catatan sistem dengan uang dan saldo yang dihitung hari ini.')}${card(`<h2 class="section-title">Ringkasan hari ini · ${dateLabel(new Date())}</h2><div class="list"><div class="list-row"><span>Pendapatan lunas</span><b>${money(tx.reduce((s,t)=>s+Number(t.total),0))}</b></div><div class="list-row"><span>Pengeluaran tercatat</span><b>${money(expenses.reduce((s,e)=>s+Number(e.amount),0))}</b></div><div class="list-row"><span>Tagihan belum lunas</span><b>${money(todayTransactions().filter(t=>t.status==='unpaid').reduce((s,t)=>s+Number(t.total),0))}</b></div></div>`)}<form id="closingForm" style="margin-top:14px">${card(`<h2 class="section-title">Hitung saldo per metode</h2><p class="section-sub">Masukkan jumlah aktual. Selisih dihitung dari pemasukan dikurangi pengeluaran yang tercatat.</p><div class="form-grid">${paymentMethods.map((m,i)=>{const key=['cash','machine','neighbor'][i],v=closing?closing[['cash_counted','qr_machine_counted','qr_neighbor_counted'][i]]:'';return `<div class="field"><label>${m} · saldo sistem ${money(expected(m))}</label><input name="${key}" type="number" min="0" step="1" value="${v}" required></div>`}).join('')}<div class="field wide"><label>Catatan</label><textarea name="note" rows="2">${esc(closing?.note||'')}</textarea></div></div><p class="notice" style="margin-top:14px">${closing?`Tutup buku terakhir diperbarui ${dateLabel(closing.closed_at)}.`:'Belum ada penutupan hari ini.'}</p><button class="btn" style="margin-top:14px">${closing?'Perbarui tutup buku':'Simpan tutup buku'}</button>`)}</form>`}

function reportPage(){
  const now=new Date(),months=[];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const tx=currentTransactions().filter(t=>t.status==='paid'&&localDate(t.paid_at||t.created_at).startsWith(key));const expenses=data.expenses.filter(e=>e.store_id===profile.store_id&&localDate(e.spent_at).startsWith(key));const revenue=data.payments.filter(p=>p.store_id===profile.store_id&&localDate(p.paid_at).startsWith(key)).reduce((s,p)=>s+Number(p.amount),0),out=expenses.reduce((s,e)=>s+Number(e.amount),0),cost=costFor(tx.map(t=>t.id)),profit=revenue-out-cost,visits=customerVisitsInMonth(key);months.push({key,label:new Intl.DateTimeFormat('id-ID',{month:'short',year:'2-digit'}).format(d),tx:tx.length,revenue,out,cost,profit,visits})}
  const series=[{label:'Pendapatan bersih',color:'#c85a32',values:months.map(m=>m.revenue)},{label:'Pengeluaran tercatat',color:'#d4a373',values:months.map(m=>m.out)},{label:'Laba sementara',color:'#347a58',values:months.map(m=>m.profit)}];
  const totalRevenue=months.reduce((s,m)=>s+m.revenue,0),totalOut=months.reduce((s,m)=>s+m.out,0),totalCost=months.reduce((s,m)=>s+m.cost,0),totalProfit=totalRevenue-totalOut-totalCost;
  const channelTotals=['self_service','kiloan_retail','shoe_service','b2b'].map(ch=>{const tx=currentTransactions().filter(t=>t.status==='paid'&&t.channel===ch&&localDate(t.paid_at||t.created_at).startsWith(months.at(-1)?.key));return [channelLabel[ch],tx.length,tx.reduce((s,t)=>s+Number(t.total),0)]});
  const importButton=['master','outlet_manager'].includes(profile.role)?'<button class="btn secondary" data-action="import-history">Impor Data</button>':'';
  return `${head('Laporan keuangan · 6 bulan','Lihat tren pendapatan, pengeluaran, perkiraan biaya langsung, laba sementara, serta volume pelanggan dan nota.',`${importButton}<button class="btn" data-action="export-report">Unduh Excel</button>`)}<div class="grid stats">${[['Pendapatan 6 bulan',money(totalRevenue)],['Pengeluaran tercatat',money(totalOut)],['Biaya langsung perkiraan',money(totalCost)],['Laba sementara',money(totalProfit)]].map(x=>card(`<div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div>`)).join('')}</div>${card(`<h2 class="section-title">Tren pendapatan, pengeluaran, dan laba</h2><p class="section-sub">Data transaksi lunas dan biaya yang tercatat per bulan</p>${lineChart(series,months.map(m=>m.label))}`)}<div class="grid split" style="margin-top:14px">${card(`<h2 class="section-title">Pendapatan bulan ini menurut layanan</h2><div class="bar-list">${channelTotals.map(([label,count,amount])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><i style="width:${Math.min(100,Math.round(amount/Math.max(1,...channelTotals.map(x=>x[2]))*100))}%"></i></div><b>${money(amount)} · ${count}</b></div>`).join('')}</div>`)}${card(`<h2 class="section-title">Volume 6 bulan</h2><div class="table-wrap"><table><thead><tr><th>Bulan</th><th>Pengunjung</th><th>Nota lunas</th><th>Rata-rata per nota</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m.label}</td><td>${m.visits}</td><td>${m.tx}</td><td>${money(m.tx?m.revenue/m.tx:0)}</td></tr>`).join('')}</tbody></table></div>`)}</div><div style="margin-top:14px">${card(`<h2 class="section-title">Rincian bulanan</h2><div class="table-wrap"><table><thead><tr><th>Bulan</th><th>Nota lunas</th><th>Pendapatan</th><th>Pengeluaran</th><th>Biaya langsung</th><th>Laba sementara</th><th>Margin</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m.label}</td><td>${m.tx}</td><td>${money(m.revenue)}</td><td>${money(m.out)}</td><td>${money(m.cost)}</td><td>${money(m.profit)}</td><td>${m.revenue?`${(m.profit/m.revenue*100).toFixed(1)}%`:'—'}</td></tr>`).join('')}</tbody></table></div><p class="notice" style="margin-top:14px">Laba sementara = transaksi lunas dikurangi pengeluaran tercatat dan biaya layanan/barang yang diatur di katalog. Ini ringkasan operasional, bukan jurnal akuntansi; data kosong berarti belum ada riwayat.</p>`)}</div>`;
}

function usersPage(){return `${head('Pengguna & hak akses','Daftar ini menunjukkan akun usaha yang sudah diberi profil akses.')}${card(`<div class="table-wrap"><table><thead><tr><th>Nama</th><th>Peran</th><th>Status</th></tr></thead><tbody>${data.profiles.map(p=>`<tr><td>${esc(p.name)}${p.id===profile.id?' · Kamu':''}</td><td>${data.memberships.filter(m=>m.user_id===p.id&&m.store_id===profile.store_id).map(m=>({master:'Master',outlet_manager:'Manajer Outlet',supervisor:'Supervisor',admin:'Admin',delivery:'Kurir',production_wash:'Produksi Cuci',production_iron:'Produksi Setrika',packing:'Packing'}[m.role]||m.role)).join(', ')||(p.role==='owner'?'Pemilik':'Kasir')}</td><td><span class="tag ${p.active?'good':'bad'}">${p.active?'Aktif':'Nonaktif'}</span></td></tr>`).join('')||`<tr><td colspan="3">Belum ada akun.</td></tr>`}</tbody></table></div><p class="notice" style="margin-top:14px">Akun baru dibuat melalui Supabase Auth dan harus diberi profil serta peran oleh pemilik. Pengaturan ini tidak mengirim undangan otomatis.</p>`)}`}
function storePage(){return `${head('Pengaturan usaha','Ubah nama usaha dan zona waktu yang dipakai ringkasan harian.',profile.role==='owner'?'<button class="btn" form="storeForm">Simpan perubahan</button>':'')} ${card(`<form id="storeForm"><div class="form-grid"><div class="field"><label>Nama usaha</label><input name="name" value="${esc(store.name)}" ${profile.role!=='owner'?'disabled':''} required></div><div class="field"><label>Zona waktu</label><select name="timezone" ${profile.role!=='owner'?'disabled':''}><option value="Asia/Jakarta" ${store.timezone==='Asia/Jakarta'?'selected':''}>WIB · Asia/Jakarta</option><option value="Asia/Makassar" ${store.timezone==='Asia/Makassar'?'selected':''}>WITA · Asia/Makassar</option><option value="Asia/Jayapura" ${store.timezone==='Asia/Jayapura'?'selected':''}>WIT · Asia/Jayapura</option></select></div></div>${profile.role!=='owner'?'<p class="notice" style="margin-top:14px">Hanya Pemilik yang dapat mengubah pengaturan usaha.</p>':''}</form>`)}`}

const pages={dashboard:dashboard,transaksi:transactionPage,kiloan:kiloanPage,pelanggan:customerPage,sdm:hrPage,layanan:servicePage,stok:stockPage,pengeluaran:expensePage,kas:cashPage,tutup:closingPage,laporan:reportPage,pengguna:usersPage,usaha:storePage};

function modal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal"><header class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Tutup">×</button></header>${body}</section></div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function serviceOptions(categories){return data.services.filter(s=>categories.includes(s.category)&&s.store_id===profile.store_id)}
function serviceOption(s){return `<option value="${s.id}" data-price="${s.price}" data-demo="${s.price_is_demo}">${esc(s.name)} · ${money(s.price)} / ${esc(s.unit)}${s.price_is_demo?' · demo':''}</option>`}
function transactionFormContent(type='Self Service'){
  const isSelf=type==='Self Service',isShoe=type==='Sepatu',main=isSelf?serviceOptions(['self_service_main']):isShoe?serviceOptions(['shoe_service']):serviceOptions(['kiloan_service']),extra=isSelf?serviceOptions(['addon','product']):[];
  const name=type==='B2B'?'Kiloan B2B':type;
  return `<form id="transactionForm" data-type="${type}"><div class="notice">${demoMode?'Pratinjau formulir. Data contoh tidak akan tersimpan.':'Pembayaran lunas menambah progres membership hanya untuk Self Service dan Kiloan Retail. Reward otomatis diterapkan hanya di jasa utama Self Service.'}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Nama pelanggan</label><input name="customerName" required placeholder="Nama lengkap"></div><div class="field"><label>Nomor WhatsApp</label><input name="whatsapp" required placeholder="08xxxxxxxxxx"></div>${!isSelf?`<div class="field"><label>Nomor pesanan / nota</label><input name="invoice" placeholder="Dibuat otomatis jika kosong"></div>${isShoe?`<div class="field"><label>Jumlah pasang</label><input name="pairs" type="number" min="1" step="1" value="1" required></div>`:`<div class="field"><label>Berat cucian (kg)</label><input name="weight" type="number" min="0.1" step="0.1" value="1" required></div>`}`:''}<div class="field wide"><label>Pilih sublayanan ${esc(name)}</label><select name="mainService" required>${main.map(serviceOption).join('')}</select></div>${isSelf&&extra.length?`<div class="field wide"><label>Layanan tambahan &amp; produk (opsional)</label><div class="checkbox-list">${extra.map(s=>`<label class="check-item"><input type="checkbox" name="extraService" value="${s.id}" data-price="${s.price}" data-demo="${s.price_is_demo}">${esc(s.name)} · ${money(s.price)}${s.price_is_demo?' <span class="demo-label">demo</span>':''}</label>`).join('')}</div></div>`:''}<div class="field"><label>Status pembayaran</label><select name="paymentStatus"><option value="paid">Lunas</option><option value="unpaid">Belum lunas</option></select></div><div class="field"><label>Metode pembayaran</label><select name="paymentMethod">${paymentMethods.map(m=>`<option>${m}</option>`).join('')}</select></div></div><div class="amount-box" style="margin-top:14px"><span>Perkiraan total</span><span id="transactionTotal">${money(Number(main[0]?.price||0))}</span></div><div class="auth-error" id="formError"></div><button class="btn" style="margin-top:14px" type="submit">${demoMode?'Simpan simulasi':'Simpan transaksi'}</button></form>`;
}
function bindTransactionForm(){const f=$('#transactionForm');if(f){f.addEventListener('input',updateTransactionTotal);f.addEventListener('change',updateTransactionTotal);f.addEventListener('submit',saveTransaction)}}
function openTransaction(type='Self Service'){transactionType=type;modal(`Transaksi ${type}`,transactionFormContent(type));bindTransactionForm()}
function readTransactionLines(form){
  const t=form.dataset.type,isSelf=t==='Self Service',isShoe=t==='Sepatu',mainService=data.services.find(s=>s.id===form.elements.mainService.value);const qty=isSelf?1:isShoe?Number(form.elements.pairs?.value||1):Number(form.elements.weight?.value||1);
  const selected=[mainService,...(isSelf?$$('input[name="extraService"]:checked',form).map(x=>data.services.find(s=>s.id===x.value)):[])].filter(Boolean);
  return selected.map((s,i)=>({service:s,name:s.name,scope:s.category,quantity:i===0?qty:1,unit_price:Number(s.price),unit_cost:Number(s.estimated_unit_cost||0),line_total:Number(s.price)*(i===0?qty:1)}));
}
function updateTransactionTotal(){const f=$('#transactionForm');if(!f)return;const lines=readTransactionLines(f);$('#transactionTotal').textContent=money(lines.reduce((n,l)=>n+l.line_total,0));}
async function findOrCreateCustomer(name,whatsapp,type){if(!whatsapp)return null;const phone=whatsapp.trim();const existing=data.customers.find(c=>c.store_id===profile.store_id&&c.whatsapp===phone);if(existing){const patch={name:name||existing.name,customer_type:type};const u=await sb.from('customers').update(patch).eq('id',existing.id);if(u.error)throw u.error;return existing.id}const r=await sb.from('customers').insert({store_id:profile.store_id,name:name||'Pelanggan',whatsapp:phone,customer_type:type}).select('id').single();if(r.error)throw r.error;return r.data.id}
function makeInvoice(prefix){const d=localDate().replaceAll('-','').slice(2);return `${prefix}-${d}-${String(Date.now()).slice(-6)}`}
async function saveTransaction(e){
  e.preventDefault();const f=e.currentTarget,b=$('button[type="submit"]',f)||$('button',f),error=$('#formError');b.disabled=true;error.textContent='';
  try{
    const type=f.dataset.type,isSelf=type==='Self Service',isShoe=type==='Sepatu',isKiloan=type==='Kiloan Retail'||type==='B2B',isB2B=type==='B2B',status=f.elements.paymentStatus.value,lines=readTransactionLines(f);if(!lines.length)throw Error('Pilih minimal satu layanan.');
    if(isKiloan&&Number(f.elements.weight.value)<=0)throw Error('Berat harus lebih dari nol.');if(isShoe&&Number(f.elements.pairs.value)<=0)throw Error('Jumlah pasang harus lebih dari nol.');
    const demo=lines.some(l=>l.service.price_is_demo);if(status==='paid'&&demo)throw Error('Harga demo belum boleh dipakai untuk pembayaran nyata. Atur harga layanan dan tandai sebagai aktif dahulu.');
    const customerId=await findOrCreateCustomer(f.elements.customerName.value.trim(),f.elements.whatsapp.value.trim(),isB2B?'b2b':'retail');
    const subtotal=lines.reduce((s,l)=>s+l.line_total,0),available= isSelf&&customerId?data.rewards.filter(r=>r.store_id===profile.store_id&&r.customer_id===customerId&&!r.used_at&&!r.revoked_at&&new Date(r.expires_at)>new Date()).sort((a,b)=>new Date(a.expires_at)-new Date(b.expires_at))[0]:null,mainAmount=lines.filter(l=>l.scope==='self_service_main').reduce((s,l)=>s+l.line_total,0),rewardDiscount=available?Math.round(mainAmount*0.25):0,amountDue=subtotal-rewardDiscount;
    const invoice=(f.elements.invoice?.value||'').trim()||makeInvoice(isSelf?'SS':isShoe?'SP':'KT');
    const created=await sb.from('transactions').insert({store_id:profile.store_id,invoice_no:invoice,customer_id:customerId,channel:isSelf?'self_service':isShoe?'shoe_service':isB2B?'b2b':'kiloan_retail',status:'unpaid',subtotal,membership_discount:0,total:subtotal,created_by:session.user.id}).select('id').single();if(created.error)throw created.error;
    const txId=created.data.id;
    const itemRows=lines.map(l=>({store_id:profile.store_id,transaction_id:txId,service_id:l.service.id,name:l.name,scope:l.scope,quantity:l.quantity,unit_price:l.unit_price,unit_cost:l.unit_cost,line_total:l.line_total}));
    const itemResult=await sb.from('transaction_items').insert(itemRows);if(itemResult.error){await sb.from('transactions').update({status:'void'}).eq('id',txId);throw itemResult.error}
    if(isKiloan){const order=await sb.from('kiloan_orders').insert({store_id:profile.store_id,transaction_id:txId,order_no:invoice,weight_kg:Number(f.elements.weight.value),status:'Masuk'});if(order.error){await sb.from('transactions').update({status:'void'}).eq('id',txId);throw order.error}}
    if(status==='paid'){
      const paid=await sb.from('transaction_payments').insert({store_id:profile.store_id,transaction_id:txId,amount:amountDue,payment_method:f.elements.paymentMethod.value,received_by:session.user.id});if(paid.error)throw paid.error;
      toast(`Transaksi lunas tersimpan${rewardDiscount?` · reward ${money(rewardDiscount)} otomatis diterapkan`:''}.`);
    }else toast('Tagihan tersimpan sebagai belum lunas.');
    closeModal();await refresh();
  }catch(err){error.textContent=err.message||'Transaksi belum berhasil disimpan.'}finally{b.disabled=false}
}

function openCustomerForm(){modal('Tambah pelanggan',`<form id="customerForm"><div class="form-grid"><div class="field"><label>Nama</label><input name="name" required></div><div class="field"><label>WhatsApp</label><input name="whatsapp" required placeholder="08xxxxxxxxxx"></div><div class="field"><label>Kategori pelanggan</label><select name="customerType"><option value="retail">Retail</option><option value="b2b">B2B</option></select></div></div><button class="btn" style="margin-top:14px">Simpan pelanggan</button></form>`);$('#customerForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const r=await sb.from('customers').upsert({store_id:profile.store_id,name:f.elements.name.value.trim(),whatsapp:f.elements.whatsapp.value.trim(),customer_type:f.elements.customerType.value},{onConflict:'store_id,whatsapp'});if(r.error)return toast(r.error.message);closeModal();await refresh();toast('Pelanggan tersimpan.')}}
function openExpenseForm(){modal('Catat pengeluaran',`<form id="expenseForm"><div class="form-grid"><div class="field"><label>Kategori</label><select name="category"><option>Operasional</option><option>Utilitas</option><option>Perlengkapan</option><option>Perbaikan</option><option>Lainnya</option></select></div><div class="field"><label>Jumlah (Rp)</label><input name="amount" type="number" min="1" required></div><div class="field"><label>Metode pembayaran</label><select name="paymentMethod">${paymentMethods.map(m=>`<option>${m}</option>`).join('')}</select></div><div class="field"><label>Catatan</label><input name="note" required placeholder="Contoh: tagihan listrik"></div></div><button class="btn" style="margin-top:14px">Simpan pengeluaran</button></form>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,r=await sb.from('expenses').insert({store_id:profile.store_id,category:f.elements.category.value,amount:Number(f.elements.amount.value),payment_method:f.elements.paymentMethod.value,note:f.elements.note.value.trim(),created_by:session.user.id});if(r.error)return toast(r.error.message);closeModal();await refresh();toast('Pengeluaran tersimpan.')}}
function openLeaveForm(){modal('Ajukan cuti',`<form id="leaveForm"><div class="form-grid"><div class="field"><label>Mulai</label><input name="start" type="date" required></div><div class="field"><label>Sampai</label><input name="end" type="date" required></div><div class="field wide"><label>Alasan</label><textarea name="reason" rows="3" required></textarea></div></div><button class="btn" style="margin-top:14px">Kirim pengajuan</button></form>`);$('#leaveForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,r=await sb.from('leave_requests').insert({store_id:profile.store_id,user_id:session.user.id,starts_on:f.elements.start.value,ends_on:f.elements.end.value,reason:f.elements.reason.value.trim()});if(r.error)return toast(r.error.message);closeModal();await refresh();toast('Pengajuan cuti tercatat.')}}
function openOutletForm(){modal('Tambah outlet',`<form id="outletForm"><p>Outlet baru dimulai dengan katalog contoh dan stok kosong. Atur tarif serta stok sebelum dipakai.</p><div class="form-grid"><div class="field wide"><label>Nama outlet</label><input name="name" required placeholder="Contoh: LifeofTetangga Cabang Selatan"></div><div class="field"><label>Zona waktu</label><select name="timezone"><option value="Asia/Jakarta">WIB · Asia/Jakarta</option><option value="Asia/Makassar">WITA · Asia/Makassar</option><option value="Asia/Jayapura">WIT · Asia/Jayapura</option></select></div></div><button class="btn" style="margin-top:14px">Buat outlet</button></form>`);$('#outletForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,r=await sb.rpc('create_outlet',{p_name:f.elements.name.value.trim(),p_timezone:f.elements.timezone.value});if(r.error)return toast(r.error.message);closeModal();profile.store_id=r.data;profile.role='owner';await refresh();toast('Outlet dibuat dengan akun Master.') }}
function openEmployeeForm(employee){const outlets=data.outlets?.length?data.outlets:[store],labels={manager:'Manajer',cashier:'Kasir',iron:'Setrika',delivery:'Delivery'};modal(employee?'Ubah karyawan':'Tambah karyawan',`<form id="employeeForm"><div class="form-grid"><div class="field"><label>Nama karyawan</label><input name="name" required maxlength="100" value="${esc(employee?.name||'')}"></div><div class="field"><label>Jabatan</label><select name="position" required>${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${employee?.position===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field wide"><label>Outlet</label><select name="store" required>${outlets.map(o=>`<option value="${o.id}" ${employee?.store_id===o.id||(!employee&&profile.store_id===o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div></div><button class="btn" style="margin-top:14px">${employee?'Simpan perubahan':'Simpan karyawan'}</button></form>`);$('#employeeForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,payload={name:f.elements.name.value.trim(),position:f.elements.position.value,store_id:f.elements.store.value};const r=employee?await sb.from('employees').update(payload).eq('id',employee.id):await sb.from('employees').insert(payload);if(r.error)return toast(r.error.message);closeModal();await refresh();toast(employee?'Data karyawan diperbarui.':'Karyawan ditambahkan.')}}
