async function saveClosing(e){e.preventDefault();const f=e.currentTarget;const row={store_id:profile.store_id,business_date:localDate(),cash_counted:Number(f.elements.cash.value),qr_machine_counted:Number(f.elements.machine.value),qr_neighbor_counted:Number(f.elements.neighbor.value),note:f.elements.note.value,closed_by:session.user.id,closed_at:new Date().toISOString()};const balance=m=>data.payments.filter(p=>p.store_id===profile.store_id&&p.payment_method===m&&localDate(p.paid_at)===row.business_date).reduce((s,p)=>s+Number(p.amount),0)-todayExpenses().filter(x=>x.payment_method===m).reduce((s,x)=>s+Number(x.amount),0);row.cash_expected=balance('Tunai');row.qr_machine_expected=balance('QR Mesin');row.qr_neighbor_expected=balance('QR Tetangga');const r=await sb.from('daily_closings').upsert(row,{onConflict:'store_id,business_date'});if(r.error)return toast(r.error.message);await refresh();toast('Tutup buku tersimpan.')}
async function xlsx(){return import('https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs')}
async function exportReport(){try{const XLSX=await xlsx(),now=new Date(),monthly=[['Bulan','Pengunjung unik per hari','Nota lunas','Pendapatan diterima','Pengeluaran tercatat','Biaya langsung perkiraan','Laba sementara','Margin laba']];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,tx=currentTransactions().filter(t=>t.status==='paid'&&localDate(t.paid_at||t.created_at).startsWith(key)),ex=data.expenses.filter(e=>e.store_id===profile.store_id&&localDate(e.spent_at).startsWith(key)),rev=data.payments.filter(p=>p.store_id===profile.store_id&&localDate(p.paid_at).startsWith(key)).reduce((s,p)=>s+Number(p.amount),0),out=ex.reduce((s,e)=>s+Number(e.amount),0),cost=costFor(tx.map(t=>t.id)),profit=rev-out-cost;monthly.push([key,customerVisitsInMonth(key),tx.length,rev,out,cost,profit,rev?profit/rev:0])}
 const txRows=currentTransactions().map(t=>{const customer=data.customers.find(c=>c.id===t.customer_id),items=currentItems().filter(i=>i.transaction_id===t.id).map(i=>`${i.name} (${i.quantity} x ${i.unit_price})`).join('; '),paid=data.payments.filter(p=>p.transaction_id===t.id).reduce((s,p)=>s+Number(p.amount),0);return [t.invoice_no,localDate(t.created_at),t.paid_at?localDate(t.paid_at):'',customer?.name||'',customer?.whatsapp||'',channelLabel[t.channel]||t.channel,t.status,items,Number(t.subtotal||0),Number(t.membership_discount||0),Number(t.total||0),paid,Number(t.total||0)-paid]});
 const paymentRows=data.payments.filter(p=>p.store_id===profile.store_id).map(p=>{const t=currentTransactions().find(x=>x.id===p.transaction_id),c=data.customers.find(x=>x.id===t?.customer_id);return [localDate(p.paid_at),t?.invoice_no||'',c?.name||'',p.payment_method,Number(p.amount)]});
 const expenseRows=data.expenses.filter(e=>e.store_id===profile.store_id).map(e=>[localDate(e.spent_at),e.category,e.note,e.payment_method,Number(e.amount)]);
 const volume=[['Bulan','Self Service','Kiloan Retail','Sepatu','B2B','Total nota']];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,counts=['self_service','kiloan_retail','shoe_service','b2b'].map(c=>currentTransactions().filter(t=>t.channel===c&&t.status==='paid'&&localDate(t.paid_at||t.created_at).startsWith(key)).length);volume.push([key,...counts,counts.reduce((a,b)=>a+b,0)])}
 const txHeader=['No Nota','Tanggal Transaksi','Tanggal Lunas','Nama Pelanggan','WhatsApp','Jenis Layanan','Status','Rincian Layanan','Subtotal','Diskon','Total','Sudah Dibayar','Sisa Tagihan'];
 const sheets=[[monthly,'Ringkasan Bulanan'],[volume,'Volume Layanan'],[[txHeader,...txRows],'Transaksi'],[[['Tanggal','No Nota','Nama Pelanggan','Metode Pembayaran','Jumlah'],...paymentRows],'Pembayaran'],[[['Tanggal','Kategori','Catatan','Metode Pembayaran','Jumlah'],...expenseRows],'Pengeluaran']];
 const wb=XLSX.utils.book_new();for(const [rows,name] of sheets)XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),name);XLSX.writeFileXLSX(wb,`LifeofTetangga-Laporan-${localDate()}.xlsx`)}catch(e){console.error(e);toast('File Excel belum berhasil dibuat. Periksa koneksi internet lalu coba lagi.')}}

const importHeaders={tx:['tanggal','tanggal_lunas','no_nota','nama_pelanggan','whatsapp','jenis_layanan','nama_layanan','kategori_item','jumlah','harga_satuan','biaya_satuan','subtotal','diskon','total','dibayar','metode_pembayaran','berat_kg','status_pesanan'],expense:['tanggal','kategori','catatan','jumlah','metode_pembayaran']};
function downloadImportTemplate(){xlsx().then(XLSX=>{const wb=XLSX.utils.book_new(),guide=[['Template impor data historis LifeofTetangga'],['Isi 1 baris untuk setiap nota transaksi. Data transaksi dan pengeluaran boleh diisi terpisah.'],['Format tanggal/tanggal_lunas: YYYY-MM-DD atau DD/MM/YYYY. Jika tanggal_lunas kosong, tanggal transaksi dipakai.'],['Nominal uang dalam Rupiah tanpa simbol Rp. Isi subtotal, diskon, total, dan dibayar sesuai nota.'],['jenis_layanan: Self Service, Kiloan Retail, B2B, atau Sepatu.'],['kategori_item: Jasa Utama Self Service, Add-on, Produk, Jasa Kiloan, Jasa Sepatu.'],['metode_pembayaran: Tunai, QR Mesin, atau QR Tetangga. Kosongkan dibayar bila belum ada pembayaran.'],['Kiloan Retail: berat_kg boleh diisi dan status_pesanan: Masuk, Proses, Selesai, Diambil.'],['Impor tidak mengubah harga katalog/stok; data lama memakai harga pada file.'],['Tanggal transaksi yang sudah ada (no_nota sama) akan dilewati.']],ws=XLSX.utils.aoa_to_sheet(guide);XLSX.utils.book_append_sheet(wb,ws,'Petunjuk');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([importHeaders.tx]),'Transaksi');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([importHeaders.expense]),'Pengeluaran');XLSX.writeFileXLSX(wb,'Template-Impor-LifeofTetangga.xlsx')}).catch(e=>{console.error(e);toast('Template Excel belum berhasil dibuat.')})}
const importState={transactions:[],expenses:[],errors:[],fileName:''};
function openImportModal(){if(demoMode)return toast('Mode pratinjau tidak terhubung ke database.');importState.transactions=[];importState.expenses=[];importState.errors=[];importState.fileName='';modal('Impor data lama',`<p class="section-sub">Masukkan transaksi dan pengeluaran lama sekaligus dari Excel. Gunakan template agar kolom serta pilihan metode pembayaran terbaca dengan benar.</p><div class="inline" style="margin:12px 0"><button class="btn secondary small" data-action="download-import-template">Unduh Template Excel</button><span class="muted">Format .xlsx atau .xls</span></div><div class="field"><label>Pilih file Excel</label><input id="historyFile" type="file" accept=".xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"></div><div id="importPreview" style="margin-top:14px"><div class="empty-state">Pilih file untuk melihat jumlah dan contoh data sebelum diimpor.</div></div><div class="inline" style="justify-content:flex-end;margin-top:16px"><button class="btn secondary" data-action="close-modal">Batal</button><button class="btn" id="confirmHistoryImport" disabled>Impor data</button></div>`);$('#historyFile').onchange=previewImportFile;$('#confirmHistoryImport').onclick=runHistoryImport}
const txt=(row,key)=>String(row[key]??'').trim();
function parseImportDate(v){if(v instanceof Date&&!Number.isNaN(v.getTime()))return v.toISOString();if(typeof v==='number'){const date=new Date(Date.UTC(1899,11,30)+v*86400000);return date.toISOString()}const s=String(v??'').trim();if(!s)return '';let m=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);if(m)return new Date(Date.UTC(+m[1],+m[2]-1,+m[3],12)).toISOString();m=s.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})/);if(m)return new Date(Date.UTC(+m[3],+m[2]-1,+m[1],12)).toISOString();const d=new Date(s);return Number.isNaN(d.getTime())?'':d.toISOString()}
function normalizeServiceType(value){return ({'self service':'self_service','self_service':'self_service','kiloan retail':'kiloan_retail','kiloan_retail':'kiloan_retail','b2b':'b2b','sepatu':'shoe_service','shoe_service':'shoe_service'})[String(value||'').toLowerCase().trim()]||''}
function normalizeScope(value,channel){const s=String(value||'').toLowerCase().trim();return ({'jasa utama self service':'self_service_main','self service':'self_service_main','self_service_main':'self_service_main','add-on':'addon','addon':'addon','produk':'product','product':'product','jasa kiloan':'kiloan_service','kiloan_service':'kiloan_service','jasa sepatu':'shoe_service','shoe_service':'shoe_service'})[s]||({self_service:'self_service_main',kiloan_retail:'kiloan_service',b2b:'kiloan_service',shoe_service:'shoe_service'}[channel]||'')}
async function previewImportFile(){const f=$('#historyFile').files?.[0],box=$('#importPreview'),button=$('#confirmHistoryImport');if(!f)return;button.disabled=true;box.innerHTML='<div class="empty-state">Membaca file Excel…</div>';try{const XLSX=await xlsx(),book=XLSX.read(new Uint8Array(await f.arrayBuffer()),{type:'array',cellDates:true}),txRows=book.Sheets.Transaksi?XLSX.utils.sheet_to_json(book.Sheets.Transaksi,{defval:'',raw:true}):[],exRows=book.Sheets.Pengeluaran?XLSX.utils.sheet_to_json(book.Sheets.Pengeluaran,{defval:'',raw:true}):[],errors=[],transactions=[],expenses=[];const seen=new Set();txRows.forEach((r,i)=>{const rowNo=i+2,date=parseImportDate(r.tanggal),paidDate=parseImportDate(r.tanggal_lunas)||date,invoice=txt(r,'no_nota'),name=txt(r,'nama_pelanggan'),phone=txt(r,'whatsapp'),channel=normalizeServiceType(r.jenis_layanan),service=txt(r,'nama_layanan'),scope=normalizeScope(r.kategori_item,channel),qty=Number(r.jumlah||1),price=Number(r.harga_satuan),subtotal=r.subtotal===''?qty*price:Number(r.subtotal),discount=Number(r.diskon||0),total=r.total===''?subtotal-discount:Number(r.total),paid=Number(r.dibayar||0),method=txt(r,'metode_pembayaran'),weight=Number(r.berat_kg||0),orderStatus=txt(r,'status_pesanan')||'Diambil';if(!invoice&&!name&&!service)return;if(!date||!invoice||!name||!channel||!service||!scope||!Number.isFinite(qty)||qty<=0||!Number.isFinite(price)||price<0||subtotal<=0||total<0||paid<0||paid>total||(paid>0&&!paymentMethods.includes(method))){errors.push(`Baris Transaksi ${rowNo}: periksa tanggal, no nota, pelanggan, layanan, jumlah, harga, total, dibayar, dan metode pembayaran.`);return}if(seen.has(invoice)){errors.push(`Baris Transaksi ${rowNo}: no nota ${invoice} muncul lebih dari sekali. Satu nota harus satu baris.`);return}seen.add(invoice);transactions.push({invoice_no:invoice,created_at:date,paid_at:paidDate,customer_name:name,whatsapp:phone,channel,service_name:service,scope,quantity:qty,unit_price:price,unit_cost:Number(r.biaya_satuan||0),subtotal,discount,total,paid_amount:paid,payment_method:method||'Tunai',weight_kg:weight,order_status:orderStatus})});exRows.forEach((r,i)=>{const rowNo=i+2,date=parseImportDate(r.tanggal),category=txt(r,'kategori'),note=txt(r,'catatan'),amount=Number(r.jumlah),method=txt(r,'metode_pembayaran');if(!category&&!note&&!r.jumlah)return;if(!date||!category||!note||!Number.isFinite(amount)||amount<=0||!paymentMethods.includes(method)){errors.push(`Baris Pengeluaran ${rowNo}: periksa tanggal, kategori, catatan, jumlah, dan metode pembayaran.`);return}expenses.push({spent_at:date,category,note,amount,payment_method:method,import_key:`hist-${date.slice(0,10)}-${i+2}-${amount}-${category.toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,12)}`})});importState.transactions=transactions;importState.expenses=expenses;importState.errors=errors;importState.fileName=f.name;const examples=transactions.slice(0,4).map(r=>`<tr><td>${esc(r.invoice_no)}</td><td>${esc(r.created_at.slice(0,10))}</td><td>${esc(r.customer_name)}</td><td>${esc(channelLabel[r.channel])}</td><td>${money(r.total)}</td></tr>`).join('');box.innerHTML=`<div class="grid thirds"><div class="check-item"><b>${transactions.length}</b><div class="muted">transaksi siap</div></div><div class="check-item"><b>${expenses.length}</b><div class="muted">pengeluaran siap</div></div><div class="check-item"><b>${errors.length}</b><div class="muted">baris perlu diperbaiki</div></div></div>${errors.length?`<div class="notice" style="margin-top:10px">${errors.slice(0,5).map(esc).join('<br>')}${errors.length>5?`<br>dan ${errors.length-5} kesalahan lainnya`:''}</div>`:''}${transactions.length?`<div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>No Nota</th><th>Tanggal</th><th>Pelanggan</th><th>Layanan</th><th>Total</th></tr></thead><tbody>${examples}</tbody></table></div>`:''}<p class="stat-foot">File: ${esc(f.name)} · Baris dengan kesalahan tidak akan diimpor. Maksimal 500 baris per proses.</p>`;button.disabled=errors.length>0||(!transactions.length&&!expenses.length)||(transactions.length+expenses.length>500)}catch(e){console.error(e);box.innerHTML='<div class="notice">File tidak terbaca. Pastikan memakai template Excel LifeofTetangga dan nama sheet Transaksi/Pengeluaran tidak diubah.</div>'}}
async function runHistoryImport(){const button=$('#confirmHistoryImport');if(!button||button.disabled||!importState.fileName)return;button.disabled=true;button.textContent='Mengimpor…';try{if(importState.transactions.length+importState.expenses.length>500)throw Error('Maksimal 500 baris dalam satu file.');const {data:result,error}=await sb.rpc('import_historical_data',{p_store_id:profile.store_id,p_transactions:importState.transactions,p_expenses:importState.expenses});if(error)throw error;closeModal();await refresh();toast(`Impor selesai: ${result.imported_transactions} transaksi, ${result.imported_expenses} pengeluaran. ${result.skipped_transactions+result.skipped_expenses} baris duplikat dilewati.`)}catch(e){console.error(e);button.disabled=false;button.textContent='Coba impor lagi';toast(e.message||'Data belum berhasil diimpor.')}}

document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
  if(a==='transact'){transactionType=b.dataset.type||'Self Service';setPage('transaksi')}
  else if(a==='transaction-tab'){transactionType=b.dataset.type;setPage('transaksi')}
  else if(a==='history')setPage('transaksi');
  else if(a==='customer')openCustomerForm();
  else if(a==='employee-add')openEmployeeForm();
  else if(a==='employee-edit')openEmployeeForm(data.employees.find(p=>p.id===b.dataset.id));
  else if(a==='employee-toggle'){const employee=data.employees.find(p=>p.id===b.dataset.id);if(employee)toggleEmployee(employee)}
  else if(a==='leave')openLeaveForm();
  else if(a==='payroll')openPayrollForm();
  else if(a==='attendance')recordAttendance();
  else if(a==='add-outlet')openOutletForm();
  else if(a==='expense')openExpenseForm();
  else if(a==='stock')openStockForm();
  else if(a==='pay')payTransaction(b.dataset.id);
  else if(a==='edit-service')openServiceForm(data.services.find(s=>s.id===b.dataset.id));
  else if(a==='close-modal')closeModal();
  else if(a==='modal-backdrop'&&e.target===b)closeModal();
  else if(a==='export-report')exportReport();
  else if(a==='import-history')openImportModal();
  else if(a==='download-import-template')downloadImportTemplate();
});
document.addEventListener('change',e=>{const o=e.target.closest('[data-action="order-status"]');if(o){if(demoMode){toast('Mode pratinjau — status pesanan contoh tidak disimpan.');render();return}updateOrder(o.dataset.id,o.value)}});
document.addEventListener('submit',e=>{if(!demoMode)return;e.preventDefault();e.stopImmediatePropagation();closeModal();toast('Mode pratinjau — perubahan tidak disimpan ke database.')},true);
document.addEventListener('submit',e=>{if(e.target.id==='closingForm')saveClosing(e)},{capture:true});
document.addEventListener('submit',async e=>{if(e.target.id==='storeForm'){e.preventDefault();if(profile.role!=='owner')return toast('Hanya pemilik yang dapat mengubah pengaturan.');const f=e.target,r=await sb.from('stores').update({name:f.elements.name.value.trim(),timezone:f.elements.timezone.value}).eq('id',store.id);if(r.error)return toast(r.error.message);await refresh();toast('Pengaturan usaha tersimpan.')}},{capture:true});
$('#menuToggle').onclick=()=>{const aside=$('#sidebar');aside.classList.toggle('mobile-open');$('#drawerShade').classList.toggle('hidden')};$('#drawerShade').onclick=()=>{$('#sidebar').classList.remove('mobile-open');$('#drawerShade').classList.add('hidden')};$('#signOut').onclick=()=>demoMode?toast('Kamu sedang berada di mode pratinjau.'):sb.auth.signOut();

if(cfg.demoPreview){try{startDemoPreview()}catch(e){console.error(e);fatal('Mode pratinjau belum dapat dimuat. '+(e.stack||e.message||''))}}else{
  try{
    if(!cfg.supabaseUrl||!cfg.publishableKey||!cfg.storeId)throw Error('Konfigurasi Supabase belum lengkap.');
    sb=createClient(cfg.supabaseUrl,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    const {data:{session:current},error}=await sb.auth.getSession();if(error)throw error;
    await startApp(current);
    sb.auth.onAuthStateChange((_event,next)=>{startApp(next)});
  }catch(e){fatal('Koneksi Supabase belum bisa dimulai. '+(e.message||''))}
}
